mapper.select:
select idenlace
from seguridad.enlaces join seguridad.enlacesroles using(idenlace)
where idenlacepadre=0 and enlacesroles.idrol in (select idrol from seguridad.usuariosroles where idusuario=#{idusuario})
group by idenlace
order by orden;

select idenlace, idenlacepadre, enlace, ruta, iconoenlace, orden
from seguridad.enlaces
where not(idenlacepadre is null) and idenlacepadre = 0;

select idenlace, idenlacepadre, enlace, ruta, iconoenlace, orden
from seguridad.enlaces
where idenlace=#{id}
